cat >> parser_test.go <<'EOF'

func TestQuotedHashAndComments(t *testing.T) {
	c := mustParse(t, "[s]\ntitle = \"Issue #42: retry\"\nnote = \"x\" # note\npath = \"C:\\\\temp\"\nport = 8080 # http\n")
	for key, want := range map[string]string{"title": "Issue #42: retry", "note": "x", "path": `C:\temp`, "port": "8080"} {
		if got := get(t, c, "s", key); got != want {
			t.Errorf("%s = %q, want %q", key, got, want)
		}
	}
}
EOF
go test ./... 2>&1 | tail; bash checks/quoted-hash.sh; echo rc=$?
